Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 12;
const int INF = 1000000;
const int MAXNODE = 205;

int N, T;
char G1[MAXN][MAXN], G2[MAXN][MAXN];
int A[MAXN][MAXN];
int R[MAXN][MAXN][MAXN][MAXN];

int dx[4] = {-1,1,0,0};
int dy[4] = {0,0,-1,1};

class Dinic {
public:
    struct Edge { int a,b,cap,flow; };

    int n, s, t;
    vector<Edge> e;
    vector<int> g[MAXNODE];
    int d[MAXNODE], ptr[MAXNODE], q[MAXNODE];

    void addEdge(int a, int b, int cap) {
        Edge e1 = {a,b,cap,0};
        Edge e2 = {b,a,0,0};
        g[a].push_back((int)e.size());
        e.push_back(e1);
        g[b].push_back((int)e.size());
        e.push_back(e2);
    }

    bool bfs() {
        int qh=0, qt=0;
        q[qt++] = s;
        memset(d, -1, n * sizeof d[0]);
        d[s] = 0;
        while (qh < qt && d[t] == -1) {
            int v = q[qh++];
            for (size_t i=0; i<g[v].size(); ++i) {
                int id = g[v][i], to = e[id].b;
                if (d[to] == -1 && e[id].flow < e[id].cap) {
                    q[qt++] = to;
                    d[to] = d[v] + 1;
                }
            }
        }
        return d[t] != -1;
    }

    int dfs(int v, int fl) {
        if (!fl) return 0;
        if (v == t) return fl;
        for (; ptr[v] < (int)g[v].size(); ++ptr[v]) {
            int id = g[v][ptr[v]], to = e[id].b;
            if (d[to] != d[v] + 1) continue;
            int pushed = dfs(to, min(fl, e[id].cap - e[id].flow));
            if (pushed) {
                e[id].flow += pushed;
                e[id^1].flow -= pushed;
                return pushed;
            }
        }
        return 0;
    }

    int maxflow() {
        int flow = 0;
        for (;;) {
            if (!bfs()) break;
            memset(ptr, 0, n * sizeof ptr[0]);
            while (int pushed = dfs(s, INF))
                flow += pushed;
        }
        return flow;
    }
};

bool canReach(int sx,int sy,int tx,int ty) {
    if (G1[sx][sy]=='Y' || G1[sx][sy]=='Z' || G1[tx][ty]=='Y' || G1[tx][ty]=='Z')
        return false;

    int dist[MAXN][MAXN];
    for(int i=0;i<N;i++)
        for(int j=0;j<N;j++)
            dist[i][j]=INF;

    queue<pair<int,int>> q;
    dist[sx][sy]=0;
    q.push({sx,sy});

    while(!q.empty()) {
        int x=q.front().first, y=q.front().second;
        q.pop();
        if (x==tx && y==ty) return true;
        if (dist[x][y] >= T || dist[x][y] >= A[x][y]) continue;
        for(int d=0;d<4;d++) {
            int nx=x+dx[d], ny=y+dy[d];
            if (nx>=0 && nx<N && ny>=0 && ny<N &&
                G1[nx][ny]!='Y' && G1[nx][ny]!='Z' &&
                dist[nx][ny]==INF &&
                dist[x][y]+1 <= A[nx][ny]) {
                dist[nx][ny]=dist[x][y]+1;
                q.push({nx,ny});
            }
        }
    }
    return false;
}

int main() {
    scanf("%d%d",&N,&T);
    for(int i=0;i<N;i++) scanf("%s",G1[i]);
    getchar();
    for(int i=0;i<N;i++) scanf("%s",G2[i]);

    for(int i=0;i<N;i++)
        for(int j=0;j<N;j++)
            A[i][j]=INF;

    queue<pair<int,int>> q;
    for(int x=0;x<N;x++)
        for(int y=0;y<N;y++)
            if (G1[x][y]=='Z') {
                for(int d=0;d<4;d++)
                    if (x+dx[d]>=0 && x+dx[d]<N && y+dy[d]>=0 && y+dy[d]<N && G1[x+dx[d]][y+dy[d]]!='Y') {
                        A[x+dx[d]][y+dy[d]]=1;
                        q.push({x+dx[d], y+dy[d]});
                    }
            }

    while(!q.empty()) {
        int x=q.front().first, y=q.front().second;
        q.pop();
        for(int d=0;d<4;d++) {
            int nx=x+dx[d], ny=y+dy[d];
            if (nx>=0 && nx<N && ny>=0 && ny<N && G1[nx][ny]!='Y' && G1[nx][ny]!='Z' && A[nx][ny]==INF) {
                A[nx][ny]=A[x][y]+1;
                q.push({nx,ny});
            }
        }
    }

    for(int x1=0;x1<N;x1++)
        for(int y1=0;y1<N;y1++)
            for(int x2=0;x2<N;x2++)
                for(int y2=0;y2<N;y2++)
                    R[x1][y1][x2][y2] = canReach(x1,y1,x2,y2) ? 1 : 0;

    Dinic din;
    din.s = 0;
    din.t = 2*N*N+1;
    din.n = 2*N*N+2;

    for(int i=0;i<N;i++)
        for(int j=0;j<N;j++) {
            if (G1[i][j]>'0' && G1[i][j]<='9')
                din.addEdge(din.s, 1+i*N+j, G1[i][j]-'0');
            if (G2[i][j]>'0' && G2[i][j]<='9')
                din.addEdge(N*N+1+i*N+j, din.t, G2[i][j]-'0');
        }

    for(int x1=0;x1<N;x1++)
        for(int y1=0;y1<N;y1++)
            for(int x2=0;x2<N;x2++)
                for(int y2=0;y2<N;y2++)
                    if (R[x1][y1][x2][y2])
                        din.addEdge(1+x1*N+y1, N*N+1+x2*N+y2, INF);

    printf("%d\n", din.maxflow());
    return 0;
}
